package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTlDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("Nakarinig ng Tandang o Asno", "O Allah, hinihiling ko sa Iyo ang Iyong kagandahang-loob (tandang). — Ako ay nagpapakupkop kay Allah mula sa Shaytan, ang isinumpa (asno).", "Nang marinig ang isang tandang na humihingi ng biyaya ni Allah; sa marinig ang isang asno bray humingi ng kanlungan mula sa Shaytan.", "Ang tandang ay nakakita ng isang anghel at ang asno ay nakakita ng isang diyablo."),
        "dua_something_liked" to DuaText("Nakakita ng Isang Kahanga-hanga (Laban sa Evil Eye)", "Kung ano ang ninais ng Allah. O Allah, pagpalain mo ito.", "Kapag nakakita ng isang kahanga-hangang pag-aari ng isang tao, manalangin para sa pagpapala.", "Ang pagdarasal para sa pagpapala ay pumipigil sa masamang mata."),
        "dua_sell_buy_debt_repaid" to DuaText("Kapag Nagbabayad ng Utang", "Pagpalain ka nawa ng Allah sa iyong pamilya at sa iyong kayamanan.", "Para sa nagpapahiram kapag nagbabayad ng utang.", "Ang pagbabalik para sa isang pautang ay salamat at pagbabayad."),
        "dua_talbiyah" to DuaText("Talbiyah", "Narito ako, O Allah, narito ako. Heto ako, Wala kang kasama, eto ako. Tiyak na ang lahat ng papuri, pagpapala at paghahari ay sa Iyo. Wala kang partner.", "Malakas pagkatapos pumasok sa ihram.", "Ang sagisag ng Hajj at Umrah."),
        "dua_yamani_hajar" to DuaText("Sa pagitan ng Rukn Yamani at Hajar Aswad", "Aming Panginoon, bigyan mo kami ng kabutihan sa mundong ito at kabutihan sa Kabilang-Buhay, at protektahan mo kami mula sa kaparusahan ng Apoy.", "Sa tawaf, sa pagitan ng Yemeni Corner at ng Black Stone.", "Binibigkas ito ng Propeta ﷺ sa lugar na ito sa tawaf."),
        "dua_safa_marwa" to DuaText("Sa Safa at Marwah", "Walang sinumang karapat-dapat sambahin maliban kay Allah, nag-iisa, walang katambal. Sa kanya ang kapangyarihan at sa Kanya ang papuri, at Siya ang may kapangyarihan sa lahat ng bagay. Walang sinumang karapat-dapat sambahin maliban kay Allah lamang; Tinupad Niya ang Kanyang pangako, tinulungan ang Kanyang lingkod at nag-iisang tinalo ang mga katunggali.", "Pag-akyat sa Safa at pagharap sa Qiblah (tatlong beses).", "Ang dhikr ng Propeta ﷺ sa Safa at Marwah."),
        "dua_arafah" to DuaText("Pinakamahusay na Dua ng Araw ng Arafah", "Walang sinumang karapat-dapat sambahin maliban kay Allah, nag-iisa, walang katambal. Sa kanya ang kapangyarihan at sa Kanya ang papuri, at Siya ang may kapangyarihan sa lahat ng bagay.", "Ang Araw ng Arafah - ang pinakamahusay na dua.", "Ang pinakamahusay na dua ay ang dua ng Araw ng Arafah, at ang pinakamahusay na mga salita ay ang mga ito."),
        "dua_takbeer_tashreeq" to DuaText("Takbeer-e-Tashreeq", "Si Allah ang Pinakamadakila, si Allah ang Pinakamadakila. Walang diyos kundi si Allah. Si Allah ang Pinakamadakila, si Allah ang Pinakamadakila, at ang lahat ng papuri ay para kay Allah.", "Pagkatapos ng bawat obligadong pagdarasal mula Fajr ng 9 Dhul-Hijjah hanggang Asr ng 13 Dhul-Hijjah.", "Iniulat mula kay Ali at Ibn Mas'ud (RA) — wajib ayon sa Hanafi."),
        "dua_zamzam" to DuaText("Pag-inom ng Zamzam", "O Allah, humihingi ako sa Iyo ng kapaki-pakinabang na kaalaman, masaganang panustos at lunas sa bawat sakit.", "Kapag umiinom ng Zamzam, gumawa ng dua para sa anumang nais mo.", "Ang zamzam ay para sa anumang inumin nito (Ibn Majah 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Pagninilay sa Paglikha", "Panginoon namin, hindi Mo nilikha ang lahat ng ito sa walang kabuluhan. Luwalhati sa Iyo, kaya't iligtas mo kami sa kaparusahan ng Apoy.", "Ang dua ng mga nagninilay sa paglikha ng langit at lupa.", "Ang dua ng mga taong may pang-unawa (ulul-albab)."),
        "dua_q_sami_na_munadiyan" to DuaText("Narinig Namin ang Tumatawag kay Faith", "Panginoon namin, narinig namin ang isang tumatawag na tumatawag sa pananampalataya, na nagsasabing 'Maniwala ka sa iyong Panginoon', at kami ay naniwala. Panginoon namin, patawarin mo kami sa aming mga kasalanan, alisin mo sa amin ang aming mga kasamaan at patayin mo kaming kasama ng mga matuwid.", "Isang panalangin para sa pananampalataya at pagkamatay kasama ng mga matuwid.", "Isang panalangin para sa pagpapatawad at isang magandang wakas."),
        "dua_q_atina_ma_waadtana" to DuaText("Ipagkaloob Mo sa Amin ang Iyong Ipinangako", "Panginoon namin, ipagkaloob Mo sa amin ang Iyong ipinangako sa amin sa pamamagitan ng Iyong mga Sugo at huwag Mo kaming kahihiyan sa Araw ng Muling Pagkabuhay. Tunay na hindi Ninyo sinisira ang Iyong pangako.", "Kanlungan mula sa kahihiyan sa Araw ng Muling Pagkabuhay.", "Naghahanap ng karangalan sa Kabilang Buhay."),
        "dua_q_israfana" to DuaText("Patawarin ang Aming mga Pagmamalabis", "Panginoon namin, patawarin mo kami sa aming mga kasalanan at pagmamalabis sa aming mga gawain, patatagin mo ang aming mga paa at tulungan mo kami laban sa mga taong hindi naniniwala.", "Ang dua ng mga kasamahan ng mga naunang Propeta.", "Isang dua para sa katatagan at pagpapatawad."),
        "dua_q_jamiun_nas" to DuaText("Iyong Iipunin ang Sangkatauhan", "Aming Panginoon, tiyak na titipunin Mo ang sangkatauhan sa isang Araw na walang pag-aalinlangan. Katotohanan, hindi sinisira ng Allah ang Kanyang pangako.", "Pagtitibay ng katiyakan sa Araw ng Muling Pagkabuhay.", "Ang dua ng mga matatag na nakasalig sa kaalaman."),
        "dua_q_maash_shahidin" to DuaText("Isulat Kami sa Kabilang ng mga Saksi", "Aming Panginoon, kami ay naniwala, kaya isulat mo kami sa mga saksi.", "Ang dua ng mga nakilala ang katotohanan at naniwala.", "Isang dua para sa pagtanggap ng pananampalataya ng isang tao."),
        "dua_q_la_tajalna_zalimin" to DuaText("Hindi Kasama ang mga Maling Gawa", "Panginoon namin, huwag mo kaming isama sa mga taong gumagawa ng masama.", "Ang dua ng mga tao ng al-A'raf.", "Kanlungan mula sa kapalaran ng mga gumagawa ng masama."),
        "dua_q_tawaffana_muslimin" to DuaText("Pasensya at Kamatayan bilang mga Muslim", "Panginoon, ibuhos mo sa amin ang pasensya at patayin mo kami bilang mga Muslim.", "Ang dua ng mga salamangkero ni Paraon noong sila ay naniwala.", "Pagtitiyaga sa pagsubok at pagtatapos sa pananampalataya."),
        "dua_q_la_tajalna_fitnah" to DuaText("Hindi Pagsubok para sa mga Mang-aapi", "Sa Allah tayo umaasa. Aming Panginoon, huwag Mo kaming gawing pagsubok sa mga taong gumagawa ng masama, at iligtas kami sa pamamagitan ng Iyong awa mula sa mga taong hindi naniniwala.", "Ang dua ng mga tao ni Musa (AS).", "Isang dua para sa pagliligtas mula sa pang-aapi at mga mapang-api."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Dua ng Nuh (AS) para sa Pagpapatawad", "Panginoon ko, nagpapakupkop ako sa Iyo mula sa paghingi sa Iyo ng hindi ko nalalaman. At kung hindi Mo ako patawarin at kaawaan, ako ay mapapabilang sa mga talunan.", "Ang dua ng pagsisisi ni Propeta Nuh (AS).", "Isang aral sa pagtatanong nang may wastong asal."),
        "dua_q_mudkhala_sidq" to DuaText("Pagpasok at Paglabas ng Katotohanan", "Panginoon ko, hayaan mo akong makapasok na may katotohanan at lumabas na may katotohanan, at bigyan mo ako mula sa Iyong sarili ng isang sumusuportang awtoridad.", "Bago pumasok sa isang bagong gawain, tahanan o lugar.", "Ang dua ay itinuro sa Propeta ﷺ sa panahon ng Hijrah."),
        "dua_q_la_tadharni_fardan" to DuaText("Dua of Zakariya (AS) — Huwag Mo Akong Iwan Mag-isa", "Panginoon ko, huwag mo akong pababayaan, at Ikaw ang pinakamahusay sa mga tagapagmana.", "Para sa mga naghahanap ng anak.", "Sa pamamagitan ng dalawang ito ay ipinagkaloob ng Allah si Yahya (AS)."),
        "dua_q_munzalan_mubarakan" to DuaText("Isang Pinagpalang Landing Place", "Panginoon ko, hayaan mo akong mapunta sa isang pinagpalang lupaing lugar, at Ikaw ang pinakamahusay sa mga nagdadala sa lupa.", "Kapag lumipat sa isang bagong tahanan o humihinto sa isang lugar — ang dua ng Nuh (AS).", "Isang panalangin para sa pagpapala sa isang bagong lugar."),
        "dua_q_amanna_faghfir" to DuaText("Naniniwala Kami, Kaya Patawarin Mo Kami", "Aming Panginoon, kami ay naniwala, kaya patawarin mo kami at kaawaan kami, at Ikaw ang pinakamabuti sa mga mahabagin.", "Ang dasal ng matuwid na mga lingkod ni Allah.", "Isang komprehensibong dua para sa pagpapatawad at awa."),
        "dua_q_isrif_jahannam" to DuaText("Iwasan ang Parusa ng Impiyerno", "Aming Panginoon, ilayo mo sa amin ang kaparusahan ng Impiyerno; sa katunayan ang parusa nito ay laging nakakapit. Sa katunayan, ito ay isang masamang pamayanan at tirahan.", "Ang dua ng mga tagapaglingkod ng Pinakamaawain ('Ibad ar-Rahman).", "Isang Quranic na dua para sa kanlungan mula sa Impiyerno."),
        "dua_q_hab_li_hukman" to DuaText("Dua ni Ibrahim (AS) - Karunungan at Jannah", "Panginoon ko, bigyan mo ako ng karunungan at isama mo ako sa mga matuwid, bigyan mo ako ng isang marangal na pagbanggit sa mga susunod na henerasyon, at gawin mo akong kabilang sa mga tagapagmana ng Hardin ng Bliss.", "Humihingi ng karunungan, samahan ng matuwid at Paraiso.", "Isang komprehensibong dua ni Ibrahim (AS)."),
        "dua_q_lut_najjini_ahli" to DuaText("Dua of Lut (AS) — Iligtas ang Aking Pamilya", "Panginoon ko, iligtas mo ako at ang aking pamilya mula sa (bunga) ng kanilang ginagawa.", "Pagprotekta sa pamilya mula sa isang kapaligiran ng kasamaan.", "Proteksyon ng pamilya mula sa kasamaan."),
        "dua_q_sulaiman_awzini" to DuaText("Dua ni Sulaiman (AS) para sa Pasasalamat", "Panginoon ko, bigyan mo ako ng pagkakataon na magpasalamat sa Iyong biyaya na Iyong ipinagkaloob sa akin at sa aking mga magulang, at gumawa ng mga mabubuting gawa na nakalulugod sa Iyo, at tanggapin ako sa pamamagitan ng Iyong awa sa Iyong mga matuwid na lingkod.", "Para sa kakayahang magpasalamat sa mga biyaya.", "Ang dalawa ng pasasalamat ni Sulayman (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Dua ni Musa (AS) — Nagkasala Ako", "Panginoon, nagkasala ako sa aking sarili, kaya patawarin mo ako.", "Agad na pagsisisi pagkatapos ng pagkakamali.", "Pinatawad ni Allah si Musa (AS)."),
        "dua_q_musa_najjini" to DuaText("Dua ni Musa (AS) — Iligtas Mo Ako sa mga Mapang-api", "Panginoon, iligtas mo ako sa mga taong gumagawa ng masama.", "Kapag natatakot sa mga mapang-api.", "Ang dua ni Musa (AS) nang umalis sa Ehipto."),
        "dua_q_lut_unsurni" to DuaText("Dua of Lut (AS) — Tulong Laban sa mga Corruptors", "Panginoon, tulungan mo ako laban sa mga taong tiwali.", "Para sa tulong laban sa mga nagpapalaganap ng katiwalian.", "Ang dua ng mga naninindigan sa katotohanan."),
        "dua_q_hab_li_salihin" to DuaText("Dua ni Ibrahim (AS) para sa isang Matuwid na Bata", "Panginoon ko, bigyan mo ako (isang anak) mula sa mga matuwid.", "Humihingi ng mabubuting anak.", "Sa pamamagitan nitong dalawang Isma'il (AS) ay ipinagkaloob."),
        "dua_q_wasita_kulla_shay" to DuaText("Dua ng mga Anghel na Nagdadala ng Trono", "Aming Panginoon, Iyong saklaw ang lahat ng bagay sa awa at kaalaman, kaya't patawarin mo ang mga nagsisi at sumusunod sa Iyong daan, at ingatan sila mula sa kaparusahan ng Impiyerno.", "Ang mga anghel na nagdadala ng Trono ay gumagawa ng dalawang ito para sa mga mananampalataya.", "Binibigkas na may layuning mapabilang sa dua ng mga anghel."),
        "dua_q_ikhwanina" to DuaText("Para sa Mga Kapatid Natin na Nauna sa Amin", "Panginoon namin, patawarin mo kami at ang aming mga kapatid na nauna sa amin sa pananampalataya, at huwag maglagay ng sama ng loob sa aming mga puso sa mga naniniwala. Aming Panginoon, Ikaw ay tunay na Mabait at Maawain.", "Isang panalangin para sa mga mananampalataya na nauna at para sa isang malinis na puso.", "Isang dua para sa marangal na mga Kasamahan (RA) at sa mga naunang mananampalataya."),
        "dua_q_alayka_tawakkalna" to DuaText("Sa Iyo Kami Umaasa (Ibrahim AS)", "Panginoon namin, sa Iyo kami umaasa, sa Iyo kami dumudulog at sa Iyo ang pagbabalik. Panginoon namin, huwag mo kaming gawing pagsubok sa mga hindi naniniwala at patawarin mo kami. Aming Panginoon, Ikaw talaga ang Makapangyarihan, ang Marunong.", "Ang dua ni Ibrahim (AS) at ng kanyang mga kasama.", "Isang dua ng pagtitiwala sa Allah at pagbabalik-loob sa Kanya."),
        "dua_q_atmim_nurana" to DuaText("Perpekto ang Ating Liwanag", "Panginoon namin, perpekto para sa amin ang aming liwanag at patawarin mo kami. Tunay na ikaw ay may kapangyarihan sa lahat ng bagay.", "Ang dua ng mga mananampalataya sa Araw ng Muling Pagkabuhay.", "Humihingi ng liwanag sa Sirat."),
        "dua_q_asiya_baytan" to DuaText("Dua ng Asiya — Isang Bahay sa Jannah", "Panginoon, magtayo para sa akin malapit sa Iyo ng isang bahay sa Paraiso, iligtas mo ako mula kay Paraon at sa kanyang mga gawa, at iligtas mo ako mula sa mga taong gumagawa ng masama.", "Ang dua ni Asiya, ang asawa ni Paraon.", "Ginawa siya ng Allah na isang halimbawa para sa mga mananampalataya."),
        "dua_adhan_response" to DuaText("Pagtugon sa Adhan", "Walang kapangyarihan at walang kapangyarihan maliban kay Allah.", "Ulitin ang sinasabi ng muezzin; at 'Hayya 'alas-salah' at 'Hayya 'alal-falah' sabihin ito.", "Ang sinumang tumugon mula sa puso ay papasok sa Paraiso."),
        "dua_adhan_shahadah" to DuaText("Pagkatapos ng Shahadah ng Muazzin", "At ako rin ay sumasaksi na walang sinumang karapat-dapat sambahin maliban kay Allah, nag-iisa, walang katambal, at na si Muhammad ﷺ ay Kanyang alipin at Sugo. Ako ay nalulugod kay Allah bilang Panginoon, kay Muhammad ﷺ bilang Sugo at sa Islam bilang relihiyon.", "Nang marinig ang patotoo ng muezzin sa pananampalataya.", "Ang kanyang mga kasalanan ay pinatawad."),
        "dua_istiftah_baid" to DuaText("Pambungad na Dua: Distance Me from Sins", "O Allah, ilayo mo ako sa aking mga kasalanan gaya ng paglayo Mo sa silangan sa kanluran. O Allah, linisin mo ako sa mga kasalanan gaya ng paglilinis ng puting damit sa dumi. O Allah, hugasan mo ang aking mga kasalanan ng tubig, niyebe at granizo.", "Pagkatapos ng pambungad na takbir (maaari ding sabihin bilang kapalit ng Sana).", "Binibigkas ito ng Propeta ﷺ sa pagitan ng takbir at ng pagbigkas."),
        "dua_hamdan_kathiran" to DuaText("Masaganang Papuri Pagkatapos ng Ruku", "Panginoon namin, sa Iyo ang papuri - sagana, dalisay at pinagpalang papuri.", "Pagkatapos bumangon mula sa ruku, kasama ang 'Rabbana lakal-hamd'.", "Mahigit sa tatlumpung anghel ang nakikipagkarera upang maging unang magtala nito."),
    )
}
